class Solution {
    public int findRotateSteps(String ring, String key) {
        int n = ring.length();
        int m = key.length();
        int[][] dp = new int[m + 1][n];
        for (int keyIndex = m - 1; keyIndex >= 0; keyIndex--) {
            java.util.Arrays.fill(dp[keyIndex], 1_000_000);
            for (int current = 0; current < n; current++) {
                for (int target = 0; target < n; target++) {
                    if (ring.charAt(target) != key.charAt(keyIndex)) continue;
                    int clockwise = Math.abs(current - target);
                    int rotate = Math.min(clockwise, n - clockwise);
                    dp[keyIndex][current] = Math.min(dp[keyIndex][current], rotate + 1 + dp[keyIndex + 1][target]);
                }
            }
        }
        return dp[0][0];
    }
}

