class Solution {
    public int findRotateSteps(String ring, String key) {
        Map<Character, List<Integer>> positions = new HashMap<>();
        for (int i = 0; i < ring.length(); i++) {
            positions.computeIfAbsent(ring.charAt(i), ignored -> new ArrayList<>()).add(i);
        }
        int[][] memo = new int[key.length()][ring.length()];
        for (int[] row : memo) Arrays.fill(row, -1);
        return dfs(ring, key, 0, 0, positions, memo);
    }

    private int dfs(String ring, String key, int keyIndex, int ringIndex,
            Map<Character, List<Integer>> positions, int[][] memo) {
        if (keyIndex == key.length()) return 0;
        if (memo[keyIndex][ringIndex] != -1) return memo[keyIndex][ringIndex];
        int n = ring.length();
        int best = Integer.MAX_VALUE;
        for (int target : positions.get(key.charAt(keyIndex))) {
            int clockwise = Math.abs(ringIndex - target);
            int rotate = Math.min(clockwise, n - clockwise);
            best = Math.min(best, rotate + 1 + dfs(ring, key, keyIndex + 1, target, positions, memo));
        }
        memo[keyIndex][ringIndex] = best;
        return best;
    }
}

import java.util.*;

class Solution {
    public int findRotateSteps(String ring, String key) {
        int n = ring.length();
        Map<Character, List<Integer>> positions = new HashMap<>();
        for (int i = 0; i < n; i++) {
            positions.computeIfAbsent(ring.charAt(i), ignored -> new ArrayList<>()).add(i);
        }

        Map<Integer, Integer> previous = new HashMap<>();
        previous.put(0, 0);
        for (int keyIndex = 0; keyIndex < key.length(); keyIndex++) {
            Map<Integer, Integer> nextCosts = new HashMap<>();
            for (int target : positions.get(key.charAt(keyIndex))) {
                int best = Integer.MAX_VALUE;
                for (Map.Entry<Integer, Integer> entry : previous.entrySet()) {
                    int current = entry.getKey();
                    int clockwise = Math.abs(current - target);
                    int rotate = Math.min(clockwise, n - clockwise);
                    best = Math.min(best, entry.getValue() + rotate + 1);
                }
                nextCosts.put(target, best);
            }
            previous = nextCosts;
        }
        return previous.values().stream().min(Integer::compareTo).orElse(0);
    }
}

import java.util.*;

class Solution {
    public int findRotateSteps(String ring, String key) {
        int n = ring.length();
        int m = key.length();
        Map<Character, List<Integer>> positions = new HashMap<>();
        for (int i = 0; i < n; i++) {
            positions.computeIfAbsent(ring.charAt(i), ignored -> new ArrayList<>()).add(i);
        }

        int[][] dist = new int[m + 1][n];
        for (int[] row : dist) Arrays.fill(row, Integer.MAX_VALUE);
        PriorityQueue<int[]> queue = new PriorityQueue<>(Comparator.comparingInt(state -> state[0]));
        dist[0][0] = 0;
        queue.offer(new int[]{0, 0, 0});

        while (!queue.isEmpty()) {
            int[] state = queue.poll();
            int cost = state[0];
            int keyIndex = state[1];
            int ringIndex = state[2];
            if (cost != dist[keyIndex][ringIndex]) continue;
            if (keyIndex == m) return cost;
            for (int target : positions.get(key.charAt(keyIndex))) {
                int clockwise = Math.abs(ringIndex - target);
                int rotate = Math.min(clockwise, n - clockwise);
                int nextCost = cost + rotate + 1;
                if (nextCost < dist[keyIndex + 1][target]) {
                    dist[keyIndex + 1][target] = nextCost;
                    queue.offer(new int[]{nextCost, keyIndex + 1, target});
                }
            }
        }
        return -1;
    }
}

class Solution {
    public int findRotateSteps(String ring, String key) {
        int n = ring.length();
        int m = key.length();
        int[][] distance = buildDistanceMatrix(n);
        int[][] dp = new int[m + 1][n];
        for (int keyIndex = m - 1; keyIndex >= 0; keyIndex--) {
            java.util.Arrays.fill(dp[keyIndex], 1_000_000);
            for (int from = 0; from < n; from++) {
                for (int to = 0; to < n; to++) {
                    if (ring.charAt(to) == key.charAt(keyIndex)) {
                        dp[keyIndex][from] = Math.min(dp[keyIndex][from], distance[from][to] + 1 + dp[keyIndex + 1][to]);
                    }
                }
            }
        }
        return dp[0][0];
    }

    private int[][] buildDistanceMatrix(int n) {
        int[][] distance = new int[n][n];
        for (int from = 0; from < n; from++) {
            for (int to = 0; to < n; to++) {
                int diff = Math.abs(from - to);
                distance[from][to] = Math.min(diff, n - diff);
            }
        }
        return distance;
    }
}
